SELECT pg_catalog.setval('public.events_id_seq', 39, true);
SELECT pg_catalog.setval('public.registrations_id_seq', 39, true);
SELECT pg_catalog.setval('public.users_id_seq', 42, true);

ALTER TABLE ONLY public.events ADD CONSTRAINT events_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.registrations ADD CONSTRAINT registrations_pkey PRIMARY KEY (id);
ALTER TABLE ONLY public.registrations ADD CONSTRAINT registrations_user_id_event_id_key UNIQUE (user_id, event_id);
ALTER TABLE ONLY public.users ADD CONSTRAINT users_email_key UNIQUE (email);
ALTER TABLE ONLY public.users ADD CONSTRAINT users_pkey PRIMARY KEY (id);

CREATE INDEX idx_events_category ON public.events USING btree (category);
CREATE INDEX idx_events_category_status ON public.events USING btree (category, status);
CREATE INDEX idx_events_coordinator ON public.events USING btree (coordinator_id);
CREATE INDEX idx_events_created_by ON public.events USING btree (created_by);
CREATE INDEX idx_events_date ON public.events USING btree (date);
CREATE INDEX idx_events_faculty_id ON public.events USING btree (faculty_id);
CREATE INDEX idx_events_organizing_club ON public.events USING btree (organizing_club);
CREATE INDEX idx_events_status ON public.events USING btree (status);
CREATE INDEX idx_registrations_event_id ON public.registrations USING btree (event_id);
CREATE INDEX idx_registrations_user_id ON public.registrations USING btree (user_id);
CREATE INDEX idx_registrations_verification ON public.registrations USING btree (verification_status);
CREATE INDEX idx_users_coordinator_type ON public.users USING btree (coordinator_type);
CREATE INDEX idx_users_department ON public.users USING btree (department);
CREATE INDEX idx_users_dept_role ON public.users USING btree (department, role);
CREATE INDEX idx_users_designation ON public.users USING btree (designation);
CREATE INDEX idx_users_email ON public.users USING btree (email);
CREATE INDEX idx_users_role ON public.users USING btree (role);

DROP TRIGGER IF EXISTS update_events_updated_at ON public.events;
CREATE TRIGGER update_events_updated_at BEFORE UPDATE ON public.events FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
DROP TRIGGER IF EXISTS update_users_updated_at ON public.users;
CREATE TRIGGER update_users_updated_at BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

ALTER TABLE ONLY public.events ADD CONSTRAINT events_coordinator_id_fkey FOREIGN KEY (coordinator_id) REFERENCES public.users(id) ON DELETE SET NULL;
ALTER TABLE ONLY public.events ADD CONSTRAINT events_created_by_fkey FOREIGN KEY (created_by) REFERENCES public.users(id) ON DELETE SET NULL;
ALTER TABLE ONLY public.events ADD CONSTRAINT events_created_by_id_fkey FOREIGN KEY (created_by_id) REFERENCES public.users(id);
ALTER TABLE ONLY public.events ADD CONSTRAINT events_faculty_id_fkey FOREIGN KEY (faculty_id) REFERENCES public.users(id) ON DELETE SET NULL;
ALTER TABLE ONLY public.registrations ADD CONSTRAINT registrations_event_id_fkey FOREIGN KEY (event_id) REFERENCES public.events(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.registrations ADD CONSTRAINT registrations_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE;
ALTER TABLE ONLY public.users ADD CONSTRAINT users_promoted_by_fkey FOREIGN KEY (promoted_by) REFERENCES public.users(id) ON DELETE SET NULL;